Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PMKS.klayout_S L LY.
Let SF := PMKS.sfoot_S L LY.
Variable sst : Type.
Variable str_at : (word -> option byte) -> Z -> sst -> Prop.
Variable str_own : sst -> list (Z * Z).
Variable str_size : sst -> Z.
Variable str_pot : sst -> credit.
Hypothesis STR_KEEP : forall (M M' : word -> option byte) os x, 0 <= os -> os + 24 <= 2 ^ 64 -> mem_grows M M' -> L5C.agree_on M M' os 24 -> str_at M os x -> str_at M' os x.
Hypothesis PB : WD.push_back_spec RSEGS AD L HI sst str_at str_own str_size str_pot 0x66444.
Hypothesis PR : VD.pr_spec RSEGS AD L HI sst str_at str_own str_size str_pot 0x3dccc.
Hypothesis DGF : VD.dgf_spec RSEGS AD L HI sst str_at str_own str_size str_pot 0x3e7f4.
Let GR3 : VD.grisu3_spec RSEGS AD L 0x3da20 := VDGB.grisu3_ok L.
Let ECWR := VDSDGF.cwr_errno L LY.

Section Body.
Variables (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet) (LBX : list (Z * Z)) (cr : credit).
Variables (so os sp r dp : Z) (x : sst).
Hypothesis K0 : K [].
Hypothesis Hso1 : sp <= so.
Hypothesis Hso2 : so + 8 <= hl_sptop L.
Hypothesis Hos1 : sp <= os.
Hypothesis Hos2 : os + 24 <= hl_sptop L.
Hypothesis APT : WD.apart24 so 8 os.
Hypothesis CR : PMSP.credit_le (str_pot x) cr.
Hypothesis SZ : str_size x + 28 <= WD.STR_MAX.
Hypothesis BRX : PMFR.brange L LBX.
Hypothesis Rsp : getr R (reg 2) = Z_to_bv 64 sp.
Hypothesis Rgp : getr R (reg 3) = Z_to_bv 64 (pa_gp AD).
Hypothesis Rtp : getr R (reg 4) = Z_to_bv 64 (pa_tp AD).
Hypothesis RAok : L5.ra_ok r.
Hypothesis Hdp : 0 <= dp <= 255.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
   regs_preserved R R' -> getr R' 10%bv = Z_to_bv 64 1 -> str_at M' os x' -> str_size x <= str_size x' <= str_size x + 28 ->
   L5C.hpres L LBX sp 14736 [(os, 24)] M M' -> PMSP.credit_keep cr cr' (str_pot x) (str_pot x') ->
   model_but_vm model model' -> hi_heap HI (str_own x' ++ LBX) cr' M' (m_vmmaps model') ->
   srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.
Definition sv (j : nat) : Z := bv_unsigned (getr R (reg j)).
Definition cells : list (Z * Z) := [(-8, r); (-16, sv 8); (-24, sv 9)].
Definition bufs : list (Z * Z) := [].
