Definition pr_pre : bvmap 5 word -> (word -> option byte) -> Z -> Z -> Z -> Prop :=
  fun R0 M0 so0 os0 sp0 => exists buf len k, getr R0 10%bv = Z_to_bv 64 buf /\ getr R0 11%bv = Z_to_bv 64 len /\ getr R0 12%bv = Z_to_bv 64 k
        /\ getr R0 13%bv = Z_to_bv 64 (-4) /\ getr R0 14%bv = Z_to_bv 64 17 /\ getr R0 15%bv = Z_to_bv 64 so0
        /\ 1 <= len <= 21 /\ -400 <= k <= 400 /\ VD.rbuf L M0 sp0 buf VD.G_BUF os0.
Definition tr_post : bvmap 5 word -> Prop := fun _ => True.
