Definition VM (len ku res : Z) : nat -> Z := fun j =>
  match j with 2%nat => sp | 33%nat => os | 34%nat => so | 35%nat => r | 36%nat => sv 8 | 37%nat => sv 9
  | 50%nat => dp | 55%nat => len | 56%nat => ku | 60%nat => res | _ => 0 end.
Local Ltac facts IV :=
  pose proof (inv_facts _ _ _ _ _ IV) as (Mh & Ml & WR & FLO & SHI & STOP & A16 & CSO & SDEF & BASE & D8 & D16 & D24);
  pose proof (svr 8) as S8; pose proof (svr 9) as S9; pose proof RAok as (Hr1 & Hr2).
Local Ltac piece P := cbn beta iota delta [VM] in P; unfold VDSDGTP.aligned in P; PMK.feed P ltac:(first [PMK.sc]).
Local Ltac pure FR2 M2 := assert (EM2 : M2 = _) by (apply functional_extensionality; exact FR2); subst M2.

