Proof.
  intros Ho Ho' MG AG (KS & OK & A8). split; [| split; [exact OK| exact A8]].
  apply (PQMF.kstr_at_keep RSEGS M M' os (fst xg) Ho Ho'); [| | | exact KS].
  - destruct (fst xg); cbn [PQMF.vs_cells fst snd]; intros i Hi; apply AG; lia.
  - intros i Hi. apply MG.
  - intros c n p _ i Hi. apply MG.
Qed.

