Lemma lw_k (k : Z) : -2 ^ 31 <= k < 2 ^ 31 -> v_lw (Z_to_bv 64 (bytes_le_to_Z (word_to_le_bytes 4 (Z_to_bv 64 k)))) = Z_to_bv 64 k.
Proof.
  intros Hk. unfold v_lw. rewrite bytes_le_N. change (2 ^ (8 * Z.of_nat 4)) with (2 ^ 32).
  rewrite Z_to_bv_unsigned. unfold bv_wrap. change (bv_modulus 64) with (2 ^ 64).
  rewrite Z_to_bv_unsigned. unfold bv_wrap. change (bv_modulus 64) with (2 ^ 64).
  assert (E : (k `mod` 2 ^ 64) `mod` 2 ^ 32 = k `mod` 2 ^ 32).
  { destruct (Z_lt_le_dec k 0) as [N|P].
    - replace (k mod 2 ^ 64) with (k + 2 ^ 32 * 2 ^ 32). 2:{ symmetry. rewrite <- (Z.mod_add k 1) by lia. apply Z.mod_small. lia. } rewrite Z.mod_add by lia. reflexivity.
    - rewrite (Z.mod_small k (2 ^ 64)) by lia. reflexivity. }
  rewrite E. pose proof (Z.mod_pos_bound k (2 ^ 32) ltac:(lia)) as B. rewrite (Z.mod_small (k mod 2 ^ 32) (2 ^ 64)) by lia.
  f_equal. change (k mod 2 ^ 32) with (bv_wrap 32 k). rewrite bv_swrap_wrap. apply bv_swrap_small. change (bv_half_modulus 32) with (2 ^ 31). lia.
Qed.

