Hypothesis Rtp : getr R (reg 4) = Z_to_bv 64 (pa_tp AD).
Hypothesis RAok : L5.ra_ok r.
Hypothesis Hdp : 0 <= dp <= 255.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : sst) (cr' : credit),
   regs_preserved R R' -> getr R' 10%bv = Z_to_bv 64 1 -> str_at M' os x' -> str_size x <= str_size x' <= str_size x + 28 ->
   (exists ds, str_txt x' = str_txt x ++ ds /\ VDC.ascii ds) ->
   L5C.hpres L LBX sp 14736 [(os, 24)] M M' -> PMSP.credit_keep cr cr' (str_pot x) (str_pot x') ->
   model_but_vm model model' -> hi_heap HI (str_own x' ++ LBX) cr' M' (m_vmmaps model') ->
   srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.
