Lemma EPI (p : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit) :
  INV p M1 model1 x1 cr1 -> 0 <= p <= 28 ->
  getr R1 (reg 2) = Z_to_bv 64 (sp - 144) -> getr R1 (reg 1) = Z_to_bv 64 r -> getr R1 (reg 10) = Z_to_bv 64 1 ->
  (forall j, In j [8; 9]%nat -> getr R1 (reg j) = Z_to_bv 64 (sv j)) ->
  (forall j, In j KEPT -> getr R1 (reg j) = getr R (reg j)) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x3e7d0 M1 model1) K.
Proof.
  intros IV Hp A2 A1 A10 AS KR. facts IV.
  destruct (rdn8_of_defined M1 (sp - 32) ltac:(lia) ltac:(lia) ltac:(apply (L5.defined_sub M1 (sp - 14736) 14736 (sp - 32) 8 SDEF); lia)) as (bs & RD).
  set (fx2 := mkFP (bvmap_set 8%bv (bv_extract 0 64 (le_bytes_to_word bs)) (@fp_regs fx1)) (@fp_csr fx1)).
  assert (MS1 : msteps RSEGS (st fx1 R1 0x3e7d0 M1) (st fx2 R1 0x3e7d4 M1)).
  { eapply mst_step; [reflexivity| | apply mst_refl].
    rewrite (fp_step_fld fx1 RSEGS R1 (Z_to_bv 64 0x3e7d0) M1 (seg_rom RSEGS) W_3e788 8%bv 2%bv 112%bv (Z_to_bv 64 (sp - 32)) bs F_3e788 eq_refl D_3e788); [| | exact RD].
    - pc4. reflexivity.
    - unfold v_addi. rewrite <- L5K.rl2 in A2. rewrite A2. rewrite L5.unsigned_lit by lia. change (bv_signed (112%bv : bv 12)) with 112. f_equal. lia. }
  unfold PMSP.cfg. eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS1|].
  set (R2 := regupd R1 2%bv (v_addi (getr R1 2%bv) (bv_signed (144%bv : bv 12)))).
  assert (MS2 : msteps RSEGS (st fx2 R1 0x3e7d4 M1) (st fx2 R2 0x3e7d8 M1)).
  { eapply mst_step; [reflexivity| | apply mst_refl].
    rewrite (step_addi RSEGS R1 (Z_to_bv 64 0x3e7d4) M1 (seg_rom RSEGS) W_3e78c 2%bv 2%bv 144%bv F_3e78c eq_refl D_3e78c). pc4. reflexivity. }
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS2|].
  assert (B2 : getr R2 (reg 2) = Z_to_bv 64 sp).
  { unfold R2. rewrite L5K.rl2. rewrite (ureg_same R1 2) by lia. unfold v_addi. rewrite A2. rewrite L5.unsigned_lit by lia.
    change (bv_signed (144%bv : bv 12)) with 144. f_equal. lia. }
  assert (O2 : forall j w, (j < 32)%nat -> j <> 2%nat -> getr R1 (reg j) = w -> getr R2 (reg j) = w) by (intros j w Hj Nj Aw; unfold R2; rewrite L5K.rl2; apply (ureg_other R1 2 j); [exact Hj| lia| exact Nj| exact Aw]).
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| |].
  { apply (PMK.ret_to RSEGS fx2 R2 M1 0x3e7d8 W_3e790 r F_3e790 eq_refl D_3e790); [apply (O2 1%nat); [lia| lia| exact A1]| lia| exact Hr2]. }
  destruct (DN p M1 model1 x1 cr1 IV Hp) as (SA & SZ1 & TXT & HP & CK & MB & HH).
  apply (KONT fx2 R2 M1 model1 x1 cr1); [| rewrite L5K.rl10; apply (O2 10%nat); [lia| lia| exact A10]|exact SA|exact SZ1|exact TXT|exact HP|exact CK|exact MB|exact HH].
  apply PMK.preserved_by_index. intros j Hj. unfold PMK.cs_all in Hj. unfold KEPT in KR. cbn in Hj.
  destruct Hj as [<-|Hj]; [rewrite B2, Rsp; reflexivity|].
  destruct Hj as [<-|Hj]; [apply (O2 3%nat); [lia| lia| apply KR; PMK.inl]|].
  destruct Hj as [<-|Hj]; [apply (O2 4%nat); [lia| lia| apply KR; PMK.inl]|].
  destruct Hj as [<-|Hj]; [apply (O2 8%nat); [lia| lia| rewrite <- sve; apply AS; PMK.inl]|].
  destruct Hj as [<-|Hj]; [apply (O2 9%nat); [lia| lia| rewrite <- sve; apply AS; PMK.inl]|].
  repeat (destruct Hj as [<-|Hj]; [apply O2; [lia| lia| apply KR; PMK.inl]|]). destruct Hj.
Qed.

