Proof.
  intros IV Hp RC1 Hlen Hk LENC KC DG. facts IV. pose proof RC1 as (A2 & A8 & KR).
  (let T := type of (VDSDGTP.vd_gtL_conc fx1 R1 M1 (VM len 0 0)) in let T := eval cbn beta iota delta [VM] in T in let T := eval unfold VDSDGTP.aligned in T in LeanFeed.pfeed_at ident:(P) (VDSDGTP.vd_gtL_conc fx1 R1 M1 (VM len 0 0)) T ltac:(cbn beta iota delta [VM]; try (unfold VDSDGTP.aligned)) ltac:(first [PMK.sc])).
  destruct P as (fx2 & R2 & M2 & MG2 & FR2 & FRZ2 & MS2 & KS2 & B11). pure FR2 M2.
  unfold PMSP.cfg. apply (PMK.spiece_ro RSEGS model1 fx1 fx2 R1 0x3e7a4 R2 0x3e7a8 M1 K Mh Ml MS2).
  pose proof (RC_ks R1 R2 VDSDGTP.KS_vd_gtL RC1 KS2 eq_refl) as RC2. pose proof RC2 as (B2 & B8 & KR2).
  (* [comment removed for export] *)
  set (v := Z_to_bv 64 (bytes_le_to_Z (word_to_le_bytes 4 (Z_to_bv 64 k)))).
  set (R3 := regupd R2 12%bv (v_lw v)).
  assert (MS3 : msteps RSEGS (st fx2 R2 0x3e7a8 M1) (st fx2 R3 0x3e7ac M1)).
  { eapply mst_step; [reflexivity| | apply mst_refl].
    rewrite (step_lw RSEGS R2 (Z_to_bv 64 0x3e7a8) M1 (seg_rom RSEGS) W_3e760 12%bv 2%bv 104%bv (word_to_le_bytes 4 (Z_to_bv 64 k)) v F_3e760 eq_refl D_3e760).
    - pc4. reflexivity.
    - unfold L5.u32_at in KC. rewrite <- KC. f_equal. unfold v_addi. rewrite <- L5K.rl2 in B2. rewrite B2. rewrite L5.unsigned_lit by lia. change (bv_signed (104%bv : bv 12)) with 104. f_equal. lia.
    - unfold v. rewrite L5.unsigned_lit; [reflexivity|]. rewrite bytes_le_N. change (2 ^ (8 * Z.of_nat 4)) with (2 ^ 32). pose proof (Z.mod_pos_bound (bv_unsigned (Z_to_bv 64 k)) (2 ^ 32) ltac:(lia)). lia. }
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS3|].
  assert (C12 : getr R3 (reg 12) = Z_to_bv 64 k) by (unfold R3; rewrite L5K.rl12; rewrite (ureg_same R2 12) by lia; unfold v; apply lw_k; lia).
  assert (RC3 : RC R3) by (unfold R3; rewrite L5K.rl12; apply (RC_upd R2 12 _ RC2); [lia| intros X; cbn in X; lia]).
  assert (C11 : getr R3 (reg 11) = Z_to_bv 64 len) by (unfold R3; rewrite L5K.rl12; apply (ureg_other R2 12 11); [lia| lia| lia| exact B11]).
  pose proof RC3 as (C2 & C8 & KR3).
  (* [comment removed for export] *)
  set (ku := if decide (0 <= k) then k else k + 2 ^ 64).
  assert (Hku : 0 <= ku < 2 ^ 64 /\ Z_to_bv 64 ku = Z_to_bv 64 k).
  { subst ku. destruct (decide (0 <= k)) as [Y|N]; [split; [lia| reflexivity]|]. split; [lia|]. apply VDKC.zbv_cong. rewrite <- (Z.mod_add k 1) by lia. f_equal; lia. }
  destruct Hku as (KUr & EKU).
  assert (C12' : getr R3 (reg 12) = Z_to_bv 64 ku) by (rewrite C12, EKU; reflexivity).
  clear C12.
  (let T := type of (VDSDGTP.vd_gtP_conc fx2 R3 M1 (VM len ku 0)) in let T := eval cbn beta iota delta [VM] in T in let T := eval unfold VDSDGTP.aligned in T in LeanFeed.pfeed_at ident:(P) (VDSDGTP.vd_gtP_conc fx2 R3 M1 (VM len ku 0)) T ltac:(cbn beta iota delta [VM]; try (unfold VDSDGTP.aligned)) ltac:(first [PMK.sc])).
  destruct P as (fx4 & R4 & M4 & MG4 & FR4 & FRZ4 & MS4 & KS4 & D1 & D10 & D13 & D14 & D15). pure FR4 M4.
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS4|].
  pose proof (RC_ks R3 R4 VDSDGTP.KS_vd_gtP RC3 KS4 eq_refl) as RC4. pose proof RC4 as (D2 & D8' & KR4). pose proof (RC_gptp R4 RC4) as (G3 & G4).
  apply (CPp p 0x3e7c0 fx4 R4 M1 model1 x1 cr1 IV ltac:(lia) ltac:(unfold VD.PR_MAX; lia) ltac:(unfold VD.PR_SCR; lia) D1 ltac:(apply VDKC.ra_lit; [lia| reflexivity]) D2 G3 G4).
  { unfold pr_pre. exists (sp - 140), len, k. rewrite L5K.rl10, L5K.rl11, L5K.rl12, L5K.rl13, L5K.rl14, L5K.rl15.
    split; [exact D10|]. split; [exact (kreg R3 R4 VDSDGTP.KS_vd_gtP 11 _ KS4 eq_refl C11)|]. split; [rewrite <- EKU; exact (kreg R3 R4 VDSDGTP.KS_vd_gtP 12 _ KS4 eq_refl C12')|].
    split; [rewrite D13; apply VDKC.zbv_cong; reflexivity|]. split; [exact D14|]. split; [exact D15|]. split; [lia|]. split; [lia|].
    unfold VD.rbuf, VD.G_BUF. split; [| exact DG]. split; [lia|]. split; [lia|]. split; [apply (L5.defined_sub M1 (sp - 14736) 14736 (sp - 140) 22 SDEF); lia| unfold WD.apart24; lia]. }
  intros n' fx5 R5 M5 model5 x5 cr5 RP5 _ Hn' IV5.
  apply (E2K n' fx5 R5 M5 model5 x5 cr5 IV5 ltac:(unfold VD.PR_MAX in Hn'; lia) (RC_call R4 R5 RC4 RP5)).
Qed.

(* [comment removed for export] *)
Lemma GK (res len k : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit) :
  INV 0 M1 model1 x1 cr1 -> RC R1 -> getr R1 (reg 9) = Z_to_bv 64 dp -> getr R1 (reg 10) = Z_to_bv 64 res -> (res = 0 \/ res = 1) ->
  1 <= len <= 21 -> -343 <= k <= 309 -> L5.u32_at RSEGS M1 (sp - 36) len -> L5.u32_at RSEGS M1 (sp - 40) k -> VDC.digits_at RSEGS M1 (sp - 140) len ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x3e78c M1 model1) K.
Proof.
  intros IV RC1 A9 A10 Hres Hlen Hk LENC KC DG. facts IV. pose proof RC1 as (A2 & A8 & KR).
  destruct Hres as [-> | ->].
  - (* [comment removed for export] *)
    assert (MS1 : msteps RSEGS (st fx1 R1 0x3e78c M1) (st fx1 R1 0x3e7dc M1)).
    { eapply mst_step; [reflexivity| | apply mst_refl].
      rewrite (step_beq_tk RSEGS R1 (Z_to_bv 64 0x3e78c) M1 (seg_rom RSEGS) W_3e744 10%bv 0%bv _ F_3e744 eq_refl D_3e744); [unfold btgt; pc4; reflexivity|].
      rewrite <- L5K.rl10 in A10. rewrite A10. unfold c_eq. reflexivity. }
    unfold PMSP.cfg. eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS1|].
    destruct (fp_step_fsgnj fx1 RSEGS R1 (Z_to_bv 64 0x3e7dc) M1 (seg_rom RSEGS) W_3e794 F_SGNJ FMT_D 10%bv 8%bv 8%bv F_3e794 eq_refl D_3e794) as (fr2 & ST2).
    set (fx2 := mkFP fr2 (@fp_csr fx1)).
    assert (MS2 : msteps RSEGS (st fx1 R1 0x3e7dc M1) (st fx2 R1 0x3e7e0 M1)).
    { eapply mst_step; [reflexivity| | apply mst_refl]. rewrite ST2. pc4. reflexivity. }
    eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS2|].
    apply (FK fx2 R1 M1 model1 x1 cr1 IV RC1 A9).
  - (* [comment removed for export] *)
    assert (MS1 : msteps RSEGS (st fx1 R1 0x3e78c M1) (st fx1 R1 0x3e790 M1)).
    { eapply mst_step; [reflexivity| | apply mst_refl].
      rewrite (step_beq_ft RSEGS R1 (Z_to_bv 64 0x3e78c) M1 (seg_rom RSEGS) W_3e744 10%bv 0%bv _ F_3e744 eq_refl D_3e744); [pc4; reflexivity|].
      rewrite <- L5K.rl10 in A10. rewrite A10. unfold c_eq. reflexivity. }
    unfold PMSP.cfg. eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS1|].
    (* [comment removed for export] *)
    set (w := reg_get (@fp_regs fx1) 8%bv). set (R2 := regupd R1 10%bv w).
    assert (MS2 : msteps RSEGS (st fx1 R1 0x3e790 M1) (st fx1 R2 0x3e794 M1)).
    { eapply mst_step; [reflexivity| | apply mst_refl].
      rewrite (fp_step_fmv_x_d fx1 RSEGS R1 (Z_to_bv 64 0x3e790) M1 (seg_rom RSEGS) W_3e748 10%bv 8%bv F_3e748 eq_refl D_3e748). pc4. reflexivity. }
    eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS2|].
    assert (RC2 : RC R2) by (unfold R2; rewrite L5K.rl10; apply (RC_upd R1 10 _ RC1); [lia| intros X; cbn in X; lia]).
    assert (B9 : getr R2 (reg 9) = Z_to_bv 64 dp) by (unfold R2; rewrite L5K.rl10; apply (ureg_other R1 10 9); [lia| lia| lia| exact A9]).
    assert (B10 : getr R2 10%bv = w) by (unfold R2; apply getr_same; intros E; apply (f_equal bv_unsigned) in E; vm_compute in E; lia).
    pose proof RC2 as (B2 & B8 & KR2). pose proof (RC_gptp R2 RC2) as (G3 & G4).
    (* [comment removed for export] *)
    destruct (c_lts w (getr R2 0%bv)) eqn:SG.
    + (* [comment removed for export] *)
      assert (MS3 : msteps RSEGS (st fx1 R2 0x3e794 M1) (st fx1 R2 0x3e798 M1)).
      { eapply mst_step; [reflexivity| | apply mst_refl].
        rewrite (step_bge_ft RSEGS R2 (Z_to_bv 64 0x3e794) M1 (seg_rom RSEGS) W_3e74c 10%bv 0%bv _ F_3e74c eq_refl D_3e74c); [pc4; reflexivity|]. rewrite B10. exact SG. }
      eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS3|].
      (let T := type of (VDSDGTP.vd_gtM_conc fx1 R2 M1 (VM 0 0 0)) in let T := eval cbn beta iota delta [VM] in T in let T := eval unfold VDSDGTP.aligned in T in LeanFeed.pfeed_at ident:(P) (VDSDGTP.vd_gtM_conc fx1 R2 M1 (VM 0 0 0)) T ltac:(cbn beta iota delta [VM]; try (unfold VDSDGTP.aligned)) ltac:(first [PMK.sc])).
      destruct P as (fx3 & R3 & M3 & MG3 & FR3 & FRZ3 & MS4 & KS3 & C1 & C10 & C11). pure FR3 M3.
      eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS4|].
      pose proof (RC_ks R2 R3 VDSDGTP.KS_vd_gtM RC2 KS3 eq_refl) as RC3. pose proof RC3 as (C2 & C8 & KR3). pose proof (RC_gptp R3 RC3) as (G3' & G4').
      apply (CLK 0 45 0x3e7a4 fx3 R3 M1 model1 x1 cr1 IV ltac:(lia) C1 ltac:(apply VDKC.ra_lit; [lia| reflexivity]) C2 G3' G4' C10 C11 ltac:(lia)).
      intros fx4 R4 M4 model4 x4 cr4 RP4 IV4 AG4.
      apply (LK 1 len k fx4 R4 M4 model4 x4 cr4 IV4 ltac:(lia) (RC_call R3 R4 RC3 RP4) Hlen Hk).
      * apply (PMF.u32_at_agree RSEGS M1 M4 (sp - 36) len); [intros i Hi; apply AG4; lia| lia| lia| exact LENC].
      * apply (PMF.u32_at_agree RSEGS M1 M4 (sp - 40) k); [intros i Hi; apply AG4; lia| lia| lia| exact KC].
      * apply (VDC.digits_at_agree RSEGS M1 M4 (sp - 140) len DG); [lia| lia| intros i Hi; apply AG4; lia].
    + (* [comment removed for export] *)
      assert (MS3 : msteps RSEGS (st fx1 R2 0x3e794 M1) (st fx1 R2 0x3e7a4 M1)).
      { eapply mst_step; [reflexivity| | apply mst_refl].
        rewrite (step_bge_tk RSEGS R2 (Z_to_bv 64 0x3e794) M1 (seg_rom RSEGS) W_3e74c 10%bv 0%bv _ F_3e74c eq_refl D_3e74c); [unfold btgt; pc4; reflexivity|]. rewrite B10. exact SG. }
      eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS3|].
      apply (LK 0 len k fx1 R2 M1 model1 x1 cr1 IV ltac:(lia) RC2 Hlen Hk LENC KC DG).
Qed.

(* [comment removed for export] *)
Lemma ZK (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit) :
  INV 0 M1 model1 x1 cr1 -> RC R1 ->
