Proof.
  intros IV RC1. facts IV. pose proof RC1 as (A2 & A8 & KR).
  (let T := type of (VDSDGTP.vd_gtZ1_conc fx1 R1 M1 (VM 0 0 0)) in let T := eval cbn beta iota delta [VM] in T in let T := eval unfold VDSDGTP.aligned in T in LeanFeed.pfeed_at ident:(P) (VDSDGTP.vd_gtZ1_conc fx1 R1 M1 (VM 0 0 0)) T ltac:(cbn beta iota delta [VM]; try (unfold VDSDGTP.aligned)) ltac:(first [PMK.sc])).
  destruct P as (fx2 & R2 & M2 & MG2 & FR2 & FRZ2 & MS2 & KS2 & B1 & B10 & B11). pure FR2 M2.
  unfold PMSP.cfg. apply (PMK.spiece_ro RSEGS model1 fx1 fx2 R1 0x3e744 R2 0x66444 M1 K Mh Ml MS2).
