  intros fx3 R3 M3 model3 x3 cr3 RP3 IV3. pose proof (RC_call R2 R3 RC2 RP3) as RC3. clear Mh Ml WR FLO SHI STOP A16 CSO SDEF BASE D8 D16 D24 S8 S9 Hr1 Hr2. facts IV3. pose proof RC3 as (C2 & C8 & KR3).
  (let T := type of (VDSDGTP.vd_gtZ2_conc fx3 R3 M3 (VM 0 0 0)) in let T := eval cbn beta iota delta [VM] in T in let T := eval unfold VDSDGTP.aligned in T in LeanFeed.pfeed_at ident:(P) (VDSDGTP.vd_gtZ2_conc fx3 R3 M3 (VM 0 0 0)) T ltac:(cbn beta iota delta [VM]; try (unfold VDSDGTP.aligned)) ltac:(first [PMK.sc])).
  destruct P as (fx4 & R4 & M4 & MG4 & FR4 & FRZ4 & MS4 & KS4 & C1 & C10 & C11). pure FR4 M4.
  unfold PMSP.cfg. apply (PMK.spiece_ro RSEGS model3 fx3 fx4 R3 0x3e750 R4 0x66444 M3 K Mh Ml MS4).
  pose proof (RC_ks R3 R4 VDSDGTP.KS_vd_gtZ2 RC3 KS4 eq_refl) as RC4. pose proof RC4 as (D2' & D8' & KR4). pose proof (RC_gptp R4 RC4) as (G3' & G4').
  apply (CL 1 46 0x3e75c fx4 R4 M3 model3 x3 cr3 IV3 ltac:(lia) C1 ltac:(apply VDKC.ra_lit; [lia| reflexivity]) D2' G3' G4' C10 C11 ltac:(lia)).
  intros fx5 R5 M5 model5 x5 cr5 RP5 IV5. pose proof (RC_call R4 R5 RC4 RP5) as RC5. clear Mh Ml WR FLO SHI STOP A16 CSO SDEF BASE D8 D16 D24 S8 S9 Hr1 Hr2. facts IV5. pose proof RC5 as (E2 & E8 & KR5).
  (let T := type of (VDSDGTP.vd_gtZ3_conc fx5 R5 M5 (VM 0 0 0)) in let T := eval cbn beta iota delta [VM] in T in let T := eval unfold VDSDGTP.aligned in T in LeanFeed.pfeed_at ident:(P) (VDSDGTP.vd_gtZ3_conc fx5 R5 M5 (VM 0 0 0)) T ltac:(cbn beta iota delta [VM]; try (unfold VDSDGTP.aligned)) ltac:(first [PMK.sc])).
  destruct P as (fx6 & R6 & M6 & MG6 & FR6 & FRZ6 & MS6 & KS6 & E1 & E10 & E11). pure FR6 M6.
  unfold PMSP.cfg. apply (PMK.spiece_ro RSEGS model5 fx5 fx6 R5 0x3e75c R6 0x66444 M5 K Mh Ml MS6).
  pose proof (RC_ks R5 R6 VDSDGTP.KS_vd_gtZ3 RC5 KS6 eq_refl) as RC6. pose proof RC6 as (F2 & F8 & KR6). pose proof (RC_gptp R6 RC6) as (G3'' & G4'').
  apply (CL 2 48 0x3e768 fx6 R6 M5 model5 x5 cr5 IV5 ltac:(lia) E1 ltac:(apply VDKC.ra_lit; [lia| reflexivity]) F2 G3'' G4'' E10 E11 ltac:(lia)).
  intros fx7 R7 M7 model7 x7 cr7 RP7 IV7.
  apply (Z4K 3 fx7 R7 M7 model7 x7 cr7 IV7 ltac:(lia) (RC_call R6 R7 RC6 RP7)).
