(* [comment removed for export] *)
Lemma NZK (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x1 : sst) (cr1 : credit) :
  INV 0 M1 model1 x1 cr1 -> RC R1 -> getr R1 (reg 10) = Z_to_bv 64 dp ->
  (bv_unsigned (reg_get (@fp_regs fx1) 10%bv)) mod 2 ^ 63 <> 0 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x3e76c M1 model1) K.
Proof.
  intros IV RC1 A10 DNZ. facts IV. pose proof RC1 as (A2 & A8 & KR). pose proof IV as (_ & MOK1 & STK1 & _).
  set (dw := reg_get (@fp_regs fx1) 10%bv) in *.
  pose proof (bv_unsigned_in_range 64 dw) as Hd. change (bv_modulus 64) with (2 ^ 64) in Hd.
  (* [comment removed for export] *)
  set (fr2 := bvmap_set 8%bv (sgnj_val F_SGNJ dw dw) (@fp_regs fx1)). set (fx2 := mkFP fr2 (@fp_csr fx1)).
  assert (MS2 : msteps RSEGS (st fx1 R1 0x3e76c M1) (st fx2 R1 0x3e770 M1)).
  { eapply mst_step; [reflexivity| | apply mst_refl].
    rewrite (VDF.fp_step_fsgnj_d fx1 RSEGS R1 (Z_to_bv 64 0x3e76c) M1 (seg_rom RSEGS) W_3e724 F_SGNJ 8%bv 10%bv 10%bv F_3e724 eq_refl D_3e724). pc4. reflexivity. }
  unfold PMSP.cfg. eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS2|].
  assert (F10 : reg_get fr2 10%bv = dw).
  { unfold fr2. change (bvmap_set 8%bv ?v (@fp_regs fx1)) with (regupd (@fp_regs fx1) 8%bv v). rewrite regupd_other; [reflexivity|]. intros E; apply (f_equal bv_unsigned) in E; vm_compute in E; lia. }
  (* [comment removed for export] *)
  set (R2 := regupd R1 9%bv (v_addi (getr R1 10%bv) (bv_signed (0%bv : bv 12)))).
  assert (MS3 : msteps RSEGS (st fx2 R1 0x3e770 M1) (st fx2 R2 0x3e774 M1)).
  { eapply mst_step; [reflexivity| | apply mst_refl].
    rewrite (step_addi RSEGS R1 (Z_to_bv 64 0x3e770) M1 (seg_rom RSEGS) W_3e728 9%bv 10%bv 0%bv F_3e728 eq_refl D_3e728). pc4. reflexivity. }
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS3|].
  assert (B9 : getr R2 (reg 9) = Z_to_bv 64 dp).
  { unfold R2. rewrite L5K.rl9. rewrite (ureg_same R1 9) by lia. unfold v_addi. rewrite <- L5K.rl10 in A10. rewrite A10. rewrite L5.unsigned_lit by lia.
    change (bv_signed (0%bv : bv 12)) with 0. f_equal. lia. }
  assert (RC2 : RC R2) by (unfold R2; rewrite L5K.rl9; apply (RC_upd R1 9 _ RC1); [lia| intros X; cbn in X; lia]).
  pose proof RC2 as (B2 & B8 & KR2).
  (* [comment removed for export] *)
  assert (OK : store_ok RSEGS M1 (Z_to_bv 64 (sp - 36)) 4%nat = true) by (replace (sp - 36) with (sp - 14736 + 14700) by lia; apply (WR 14700 4%nat); cbn; lia).
  set (M2 := wbytes M1 (Z_to_bv 64 (sp - 36)) (Z_to_le_bytes 4 (bv_unsigned (low32 (getr R2 0%bv))))).
  assert (MS4 : msteps RSEGS (st fx2 R2 0x3e774 M1) (st fx2 R2 0x3e778 M2)).
  { eapply mst_step; [reflexivity| | apply mst_refl].
    rewrite (step_sw fx2 RSEGS R2 (Z_to_bv 64 0x3e774) M1 (seg_rom RSEGS) W_3e72c 2%bv 0%bv 108%bv F_3e72c eq_refl D_3e72c).
    - pc4. unfold M2. rewrite <- L5K.rl2 in B2. rewrite B2. unfold v_addi. rewrite L5.unsigned_lit by lia. change (bv_signed (108%bv : bv 12)) with 108.
      replace (sp - 144 + 108) with (sp - 36) by lia. reflexivity.
    - rewrite <- L5K.rl2 in B2. rewrite B2. unfold v_addi. rewrite L5.unsigned_lit by lia. change (bv_signed (108%bv : bv 12)) with 108. replace (sp - 144 + 108) with (sp - 36) by lia. exact OK. }
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS4|].
  assert (LEN4 : length (Z_to_le_bytes 4 (bv_unsigned (low32 (getr R2 0%bv)))) = 4%nat) by (change (getr R2 0%bv) with (Z_to_bv 64 0); reflexivity).
  assert (GR2 : mem_grows M1 M2) by (unfold M2; apply wbytes_grows).
  assert (FRZ2 : forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 36 <= i < sp - 36 + 4) -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)).
  { intros i Hi Ni. unfold M2. destruct (Z_lt_le_dec i (sp - 36)) as [LT|GE].
    + apply wbytes_below; rewrite ?LEN4, !L5.unsigned_lit by lia; cbn [Z.of_nat]; lia.
    + apply wbytes_above. rewrite LEN4, !L5.unsigned_lit by lia. cbn. lia. }
  assert (IV2 : INV 0 M2 model1 x1 cr1) by (apply (FRW 0 M1 M2 model1 x1 cr1 (sp - 36) 4 IV GR2 FRZ2); lia).
  clear Mh Ml WR FLO SHI STOP A16 CSO SDEF BASE D8 D16 D24 S8 S9 Hr1 Hr2. facts IV2. pose proof IV2 as (_ & _ & STK2 & _).
  (* [comment removed for export] *)
  set (fr3 := bvmap_set 10%bv (sgnj_val F_SGNJX dw dw) fr2). set (fx3 := mkFP fr3 (@fp_csr fx1)).
  assert (MS5 : msteps RSEGS (st fx2 R2 0x3e778 M2) (st fx3 R2 0x3e77c M2)).
