  assert (BRX : PMFR.brange L LBX) by (apply (PMFR.brange_incl L LBX _ BRc); apply incl_appr; apply incl_refl).
  pose proof (L5C.stk_writable RSEGS _ M sp 14736 STK) as WR. pose proof (L5C.stk_floor _ M sp 14736 STK) as FLO.
  assert (Hdp2 : 0 <= dp <= 255) by lia.
  (let T := type of (VDSDGTP.vd_gtA_conc fx R M (fun j : nat => match j with 2%nat => sp | 34%nat => so | 50%nat => dp | _ => 0 end)) in let T := eval cbn beta iota in T in let T := eval unfold VDSDGTP.aligned in T in LeanFeed.pfeed_at ident:(P) (VDSDGTP.vd_gtA_conc fx R M (fun j : nat => match j with 2%nat => sp | 34%nat => so | 50%nat => dp | _ => 0 end)) T ltac:(cbn beta iota; try (unfold VDSDGTP.aligned)) ltac:(first [PMK.sc])).
  destruct P as (fx1 & R1 & M1 & MG1 & FR1 & FRZ1 & MS1 & KS1 & B2 & C24 & C16 & C8).
  rewrite Rra, L5.unsigned_lit in C8 by lia.
  set (W := fun a => sp - 144 <= a < sp - 144 + 144).
  assert (PF : forall a, W a -> sp - 14736 <= a < sp) by (intros a Y; unfold W in Y; lia).
  assert (FRZ' : forall i : Z, 0 <= i < 2 ^ 64 -> ~ (sp - 144 <= i < sp) -> M1 (Z_to_bv 64 i) = M (Z_to_bv 64 i)) by (intros i Hi Ni; apply FRZ1; [exact Hi| lia]).
  unfold PMSP.cfg.
  apply (PMK.spiece RSEGS L HI KL HIok (str_own x ++ LBX) cr M model fx fx1 R 0x3e720 R1 0x3e730 M1 W K HH Mh Ml ltac:(lia) MS1 MG1 FRZ1).
