    + apply wbytes_above. rewrite length_N_to_le_bytes, !L5.unsigned_lit by lia. cbn. lia. }
  pose proof (inv_facts R M model LBX cr so os sp r dp x Hdp2 _ _ _ _ _ IV2) as (_ & _ & WR2 & _).
  (let T := type of (VDSDGTP.vd_gtA2_conc fx1 R1 M2 (fun j : nat => match j with 2%nat => sp | 34%nat => so | _ => 0 end)) in let T := eval cbn beta iota in T in let T := eval unfold VDSDGTP.aligned in T in LeanFeed.pfeed_at ident:(P) (VDSDGTP.vd_gtA2_conc fx1 R1 M2 (fun j : nat => match j with 2%nat => sp | 34%nat => so | _ => 0 end)) T ltac:(cbn beta iota; try (unfold VDSDGTP.aligned)) ltac:(first [PMK.sc])).
  destruct P as (fx3 & R3 & M3 & _ & FR3 & _ & MS3 & KS3 & B8).
