  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MS3|].
  assert (RC3 : RC R so sp R3).
  { unfold RC. split; [rewrite (KS3 2%nat) by PMK.inl; exact B2|]. split; [exact B8|]. intros j Hj. rewrite (KS3 j); [apply KS1|]; unfold KEPT in Hj; cbn in Hj; repeat (destruct Hj as [<-|Hj]; [PMK.inl|]); destruct Hj. }
  assert (T10 : getr R3 (reg 10) = Z_to_bv 64 dp) by (rewrite (KS3 10%nat) by PMK.inl; exact K10).
  (* [comment removed for export] *)
  set (fr4 := bvmap_set 15%bv (getr R3 0%bv) (@fp_regs fx3)). set (fx4 := mkFP fr4 (@fp_csr fx3)).
  assert (MSb : msteps RSEGS (st fx3 R3 0x3e738 M2) (st fx4 R3 0x3e73c M2)).
  { eapply mst_step; [reflexivity| | apply mst_refl].
    rewrite (fp_step_fmv_d_x fx3 RSEGS R3 (Z_to_bv 64 0x3e738) M2 (seg_rom RSEGS) W_3e6f0 15%bv 0%bv F_3e6f0 eq_refl D_3e6f0). pc4. reflexivity. }
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MSb|].
  assert (F15 : reg_get fr4 15%bv = Z_to_bv 64 0) by (unfold fr4; change (bvmap_set 15%bv (getr R3 0%bv) (@fp_regs fx3)) with (regupd (@fp_regs fx3) 15%bv (getr R3 0%bv)); rewrite regupd_same; reflexivity).
  assert (F10 : reg_get fr4 10%bv = reg_get (@fp_regs fx3) 10%bv) by (unfold fr4; change (bvmap_set 15%bv (getr R3 0%bv) (@fp_regs fx3)) with (regupd (@fp_regs fx3) 15%bv (getr R3 0%bv)); apply regupd_other; intros E; apply (f_equal bv_unsigned) in E; vm_compute in E; lia).
  set (dw := reg_get (@fp_regs fx3) 10%bv) in *. set (d := bv_unsigned dw).
  pose proof (bv_unsigned_in_range 64 dw) as Hd. change (bv_modulus 64) with (2 ^ 64) in Hd. change (bv_unsigned dw) with d in Hd.
  apply (FRMG.with_frm RSEGS); [exact K0|]. intros FZ4.
  destruct (VDF.fp_step_feq_d fx4 RSEGS R3 (Z_to_bv 64 0x3e73c) M2 (seg_rom RSEGS) W_3e6f4 11%bv 10%bv 15%bv F_3e6f4 eq_refl D_3e6f4 FZ4) as (cs5 & _ & ST5).
  cbn [fp_regs fx4] in ST5. rewrite F15, F10, L5.unsigned_lit in ST5 by lia. change (bv_unsigned dw) with d in ST5.
  set (fx5 := mkFP fr4 cs5). set (bz := fst (fp_eq fmt_double d 0)) in *.
  set (R5 := regupd R3 11%bv (if bz then Z_to_bv 64 1 else Z_to_bv 64 0)).
  assert (MSc : msteps RSEGS (st fx4 R3 0x3e73c M2) (st fx5 R5 0x3e740 M2)).
  { eapply mst_step; [reflexivity| | apply mst_refl]. rewrite ST5. pc4. reflexivity. }
  eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MSc|].
  assert (RC5 : RC R so sp R5) by (unfold R5; rewrite L5K.rl11; apply (RC_upd R so sp R3 11 _ RC3); [lia| intros X; cbn in X; lia]).
  assert (U10 : getr R5 (reg 10) = Z_to_bv 64 dp) by (unfold R5; rewrite L5K.rl11; apply (ureg_other R3 11 10); [lia| lia| lia| exact T10]).
  assert (U11 : getr R5 11%bv = (if bz then Z_to_bv 64 1 else Z_to_bv 64 0)) by (unfold R5; apply getr_same; intros E; apply (f_equal bv_unsigned) in E; vm_compute in E; lia).
  assert (F10' : reg_get (@fp_regs fx5) 10%bv = dw) by (cbn [fp_regs fx5]; exact F10).
  destruct bz eqn:E0.
  - (* [comment removed for export] *)
    assert (MSd : msteps RSEGS (st fx5 R5 0x3e740 M2) (st fx5 R5 0x3e744 M2)).
    { eapply mst_step; [reflexivity| | apply mst_refl].
      rewrite (step_beq_ft RSEGS R5 (Z_to_bv 64 0x3e740) M2 (seg_rom RSEGS) W_3e6f8 11%bv 0%bv _ F_3e6f8 eq_refl D_3e6f8); [pc4; reflexivity|]. rewrite U11. unfold c_eq. reflexivity. }
