    eapply (L5.cps_of_msteps RSEGS); [exact Mh| exact Ml| exact MSd|].
    apply (NZK R M model K LBX cr so os sp r dp x K0 Hso1 Hso2 Hos1 Hos2 APT CR SZ BRX Rsp Rgp Rtp RAok Hdp2 KONT fx5 R5 M2 model x cr IV2 RC5 U10).
    rewrite F10'. exact DNZ.
