From OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib Require Import BMode.
Import ListNotations. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQAWDOK.
Import PMS. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis OPN : PQAS.opnew_spec_n RSEGS AD L HI PQAS.NREQ.
Hypothesis OPD : PMS.opdel_spec L HI.
Hypothesis SNP : WDL.snprintf_spec RSEGS AD L 0xaedd8 WDL.FMT_G_PLAIN.
Hypothesis STRTOD : WDL.strtod_spec RSEGS AD L 0xb8c20.
Let KL := PMKS.klayout_S L LY.
(* [comment removed for export] *)
Let GR3 : VDC.grisu3_specC RSEGS AD L 0x3da20 := VDGBC.grisu3_ok L.

(* [comment removed for export] *)
Definition sst : Type := (PQAS.wd_sst * list Z)%type.
Definition str_at (M : word -> option byte) (os : Z) (s : sst) : Prop := PQAS.wd_str_at RSEGS M os (fst s) /\ NEM.kcontent RSEGS M os (fst (fst s)) (snd s).
Definition str_own (s : sst) : list (Z * Z) := PQAS.wd_str_own (fst s).
Definition str_size (s : sst) : Z := PQAS.wd_str_size (fst s).
Definition str_pot (s : sst) : credit := PQAS.wd_str_pot L (fst s).
Definition str_txt (s : sst) : list Z := snd s.

Lemma str_keep : VDC.str_keepC L HI sst str_at str_own.
Proof.
  intros M M' Mh os [[x g] bs] LBX cr VM P Ho Ho' TOP HH MG FR HP AG (SA & KC). unfold str_own, PQAS.wd_str_own in HH. cbn [fst snd] in *.
  split; [exact (VDSOP.wd_str_keep L M M' os (x, g) Ho Ho' MG AG SA)|].
  destruct SA as (KS & _ & _).
  apply (PNMK.kcontent_agree RSEGS M M' os x bs Ho Ho' AG); [| exact KS| exact KC].
  intros c n p ->. cbn [PM.vs_own app] in HH.
  destruct (proj1 (hio_wf L SCFG HI HIok _ _ _ _ HH) (p, c) (or_introl eq_refl)) as ((B0 & B1 & B2 & B3 & B4) & _ & _). cbn [fst snd] in B0, B1, B2, B3, B4.
  pose proof (PMK.kl_errno RSEGS L KL) as (E1 & E2). pose proof (PMK.kl_img RSEGS L KL) as (I1 & I2).
  pose proof (ly_img_lo L LY) as IL. pose proof (ly_img_hi L LY) as IH.
  split; [lia|]. split; [lia|].
  intros i Hi. apply FR; [lia|]. intros Pi. destruct (HP i Pi) as [X|X]; [lia|]. unfold in_errno in X. lia.
Qed.

Lemma push_backC : VDC.push_back_specC RSEGS AD L HI sst str_at str_own str_size str_pot str_txt 0x66444.
Proof.
  intros fx R M model K LBX cr os c sp r [[x g] bs] HH MOK K0 ENT R10 R11 Hc ((KS & OK & O8) & KC) Hsz Hsp Hos BASE CR KONT.
  unfold str_own, str_size, str_pot, PQAS.wd_str_own, PQAS.wd_str_size, PQAS.wd_str_pot in *. cbn [fst snd] in *.
  apply (PQADPBC.pb_ok L HI LY HIok OPN OPD fx R M model K LBX cr os c sp r PQM.SMK g x bs HH MOK K0 ENT R10 R11 ltac:(lia) KS KC OK
           ltac:(unfold PQAS.SMMAX, PQM.SMK; lia) ltac:(unfold WD.STR_MAX, PQM.SMK in *; lia) Hsp Hos O8 CR).
  intros fx' R' M' model' x' g' cr' RP KS' KC' OK' Esz HP CK MB HH'.
  apply (KONT fx' R' M' model' ((x', g'), bs ++ [c]) cr' RP); cbn [fst snd]; [| lia| reflexivity| exact HP| exact CK| exact MB| exact HH'].
  split; [| exact KC']. split; [exact KS'|]. split; [exact OK'| exact O8].
Qed.

Theorem wd_okC : PQAWDC.wd_specC RSEGS AD L HI 0x3d2cc.
Proof.
  intros fx R M model K LBX cr o so os sp r g x bs HH MOK K0 ENT R10 R11 WDAT CSO KS KC OK O8 Hsz Ho1 Ho2 Hso1 Hso2 Hos1 Hos2 AP1 AP2 BASE CR KONT.
  apply (VDSOPC.wd_ok L HI LY HIok sst str_at str_own str_size str_pot str_txt str_keep push_backC SNP STRTOD GR3 push_backC SNP STRTOD
           fx R M model K LBX cr o so os sp r ((x, g), bs) HH MOK K0 ENT R10 R11 WDAT CSO).
  - split; [split; [exact KS| split; [exact OK| exact O8]]| exact KC].
  - unfold str_size, PQAS.wd_str_size. cbn [fst]. unfold WD.STR_MAX, PQM.SMK in *. lia.
  - exact Ho1.
  - exact Ho2.
  - exact Hso1.
  - exact Hso2.
  - exact Hos1.
  - exact Hos2.
  - exact AP1.
  - exact AP2.
  - exact BASE.
  - exact CR.
  - intros fx' R' M' model' [[x' g'] bs'] cr' RP ((KS' & OK' & _) & KC') SZ' (ds & E & AS) HP CK MB HH'.
    unfold str_size, str_txt, str_pot, str_own, PQAS.wd_str_size, PQAS.wd_str_pot, PQAS.wd_str_own in *. cbn [fst snd] in *. subst bs'.
    apply (KONT fx' R' M' model' x' g' cr' ds RP KS' KC'); [exact AS| exact OK'| lia| exact HP| exact CK| exact MB| exact HH'].
Qed.
End WithHeap.
End PQAWDOK.

End PnAdWdOkC.
